// Method: Tween::bind_node
static JSValue js_Tween_bind_node(JSContext* ctx, JSValueConst this_val, int argc, JSValueConst* argv) {
    if (argc < 1) {
        return JS_ThrowTypeError(ctx, "Tween.bind_node: missing handle argument");
    }

    int64_t handle;
    if (JS_ToInt64(ctx, &handle, argv[0]) < 0) {
        return JS_ThrowTypeError(ctx, "Tween.bind_node: invalid handle");
    }

    QuickJSContext* qjs_ctx = get_qjs_ctx(ctx);
    if (!qjs_ctx || !qjs_ctx->get_object_registry()) {
        return JS_ThrowInternalError(ctx, "Context not initialized");
    }

    // Check WRITE rate limit (PRD Section 6.4)
    ExecutionLimiter* limiter = qjs_ctx->get_execution_limiter();
    if (limiter && !limiter->check_api_rate_limit(ApiCategory::WRITE)) {
        return JS_ThrowInternalError(ctx, "Tween.bind_node: write rate limit exceeded");
    }

    Object* obj = qjs_ctx->get_object_registry()->get_object(handle);
    if (!obj) {
        return JS_ThrowTypeError(ctx, "Tween.bind_node: invalid or freed object");
    }

    Tween* typed_obj = Object::cast_to<Tween>(obj);
    if (!typed_obj) {
        return JS_ThrowTypeError(ctx, "Tween.bind_node: object is not a Tween");
    }

    // Argument count check (excluding handle) - only required args
    if (argc < 2) {
        return JS_ThrowTypeError(ctx, "Tween.bind_node: expected at least 1 arguments, got %d", argc - 1);
    }

    // Convert arguments
    Node* arg_node = nullptr;
    if (JS_IsNumber(argv[1])) {
        // Direct handle (unwrapped by JS proxy)
        int64_t h_node; JS_ToInt64(ctx, &h_node, argv[1]);
        Object* obj_node = qjs_ctx->get_object_registry()->get_object(h_node);
        arg_node = reinterpret_cast<Node*>(obj_node);
    } else {
        // Object with __handle property
        JSValue jh_node = JS_GetPropertyStr(ctx, argv[1], "__handle");
        if (!JS_IsUndefined(jh_node)) {
            int64_t h_node; JS_ToInt64(ctx, &h_node, jh_node);
            Object* obj_node = qjs_ctx->get_object_registry()->get_object(h_node);
            arg_node = reinterpret_cast<Node*>(obj_node);
        }
        JS_FreeValue(ctx, jh_node);
    }

    Ref<Tween> result = typed_obj->bind_node(arg_node);
    if (result.is_null()) return JS_NULL;
    Object* ret_obj_ptr = result.ptr();
    int64_t ret_handle = qjs_ctx->get_object_registry()->get_or_create_handle(ret_obj_ptr);
    // Store class name in local String to avoid dangling pointer from temporary
    String ret_class_str = ret_obj_ptr->get_class();
    CharString ret_class_utf8 = ret_class_str.utf8();
    const char* ret_class_name = ret_class_utf8.get_data();
    // Use __wrap_existing_godot_object to create a proper Proxy with method/property access
    JSValue global = JS_GetGlobalObject(ctx);
    JSValue wrap_fn = JS_GetPropertyStr(ctx, global, "__wrap_existing_godot_object");
    if (JS_IsFunction(ctx, wrap_fn)) {
        JSValue args[2] = { JS_NewInt64(ctx, ret_handle), JS_NewString(ctx, ret_class_name) };
        JSValue wrapped = JS_Call(ctx, wrap_fn, JS_UNDEFINED, 2, args);
        JS_FreeValue(ctx, args[0]);
        JS_FreeValue(ctx, args[1]);
        JS_FreeValue(ctx, wrap_fn);
        JS_FreeValue(ctx, global);
        return wrapped;
    }
    JS_FreeValue(ctx, wrap_fn);
    JS_FreeValue(ctx, global);
    // Fallback: return raw object
    JSValue ret_obj = JS_NewObject(ctx);
    JS_SetPropertyStr(ctx, ret_obj, "__handle", JS_NewInt64(ctx, ret_handle));
    JS_SetPropertyStr(ctx, ret_obj, "__class", JS_NewString(ctx, ret_class_name));
    return ret_obj;
}

